package com.careerpilot.interview;
import com.careerpilot.exception.NotFoundException;import com.careerpilot.modules.auth.entity.User;import com.careerpilot.modules.careerai.dto.CareerAiDtos.*;import com.careerpilot.modules.careerai.service.CareerAiService;import com.careerpilot.modules.interview.dto.InterviewDtos.SubmitAnswerRequest;import com.careerpilot.modules.interview.entity.*;import com.careerpilot.modules.interview.repository.InterviewSessionRepository;import com.careerpilot.modules.interview.service.InterviewSessionService;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class InterviewSessionServiceTest{private final InterviewSessionRepository repository=mock(InterviewSessionRepository.class);private final CareerAiService ai=mock(CareerAiService.class);private final InterviewSessionService service=new InterviewSessionService(repository,ai,new ObjectMapper());private User user;private InterviewSession session;
 @BeforeEach void setup(){user=new User();user.setId(UUID.randomUUID());session=new InterviewSession();session.setId(UUID.randomUUID());session.setUser(user);session.setTargetCareer("Backend Developer");session.setInterviewType("TECHNICAL");session.setMode(InterviewMode.TEXT);session.setQuestionCount(1);session.setStatus(InterviewStatus.IN_PROGRESS);session.setCurrentQuestion("Explain dependency injection.");when(repository.findByIdAndUserId(session.getId(),user.getId())).thenReturn(Optional.of(session));when(ai.interview(eq(user),any())).thenReturn(new InterviewResponse("Backend Developer","TECHNICAL","How does it help testing?",new InterviewFeedback(List.of("Clear definition"),List.of("Add an example"),"Testing",new InterviewScores(80,90,70,60,85),"A stronger answer",List.of("Dependency Injection")),"GEMINI","test-model","test"));}
 @Test void submittedAnswerIsPersistedAndCompletesSessionWithAggregate(){var result=service.answer(user,session.getId(),new SubmitAnswerRequest("Dependency injection supplies dependencies externally.",42));assertThat(result.status()).isEqualTo(InterviewStatus.COMPLETED);assertThat(result.completedAnswers()).isOne();assertThat(result.overallCoachingScore()).isEqualTo(77);assertThat(result.answers().getFirst().answerDurationSeconds()).isEqualTo(42);verify(repository).save(session);}
 @Test void completedAttemptIsImmutable(){session.setStatus(InterviewStatus.COMPLETED);assertThatThrownBy(()->service.answer(user,session.getId(),new SubmitAnswerRequest("answer",null))).hasMessageContaining("already complete");verifyNoInteractions(ai);}
 @Test void crossUserAccessIsRejected(){var other=new User();other.setId(UUID.randomUUID());assertThatThrownBy(()->service.get(other,session.getId())).isInstanceOf(NotFoundException.class);}
}
